/// A prop the contract marks `variants = false` has no grid, and neither has
/// one that is not an enum. Both answer with an empty tree, which draws an
/// empty figure rather than a wrong one.
#[allow(
    clippy::too_many_lines,
    reason = "one arm per specimen, and the specimen set is the point"
)]
